   119  TiffRootIFDOwner TiffIFD::parseDngPrivateData(NORangesSet<Buffer>* ifds,
   120                                                TiffEntry* t) {
   121    assert(ifds);
   122
   123    /*
   124    1. Six bytes containing the zero-terminated string "Adobe". (The DNG specification calls for the DNGPrivateData tag to start with an ASCII string identifying the creator/format).
   125    2. 4 bytes: an ASCII string ("MakN" for a Makernote),  indicating what sort of data is being stored here. Note that this is not zero-terminated.
   126    3. A four-byte count (number of data bytes following); this is the length of the original MakerNote data. (This is always in "most significant byte first" format).
   127    4. 2 bytes: the byte-order indicator from the original file (the usual 'MM'/4D4D or 'II'/4949).
   128    5. 4 bytes: the original file offset for the MakerNote tag data (stored according to the byte order given above).
   129    6. The contents of the MakerNote tag. This is a simple byte-for-byte copy, with no modification.
   130    */
   131    ByteStream& bs = t->getData();
   132    if (!bs.skipPrefix("Adobe", 6))
   133      ThrowTPE("Not Adobe Private data");
   134
   135    if (!bs.skipPrefix("MakN", 4))
   136      ThrowTPE("Not Makernote");
   137
   138    bs.setByteOrder(Endianness::big);
   139    uint32 makerNoteSize = bs.getU32();
   140    if (makerNoteSize != bs.getRemainSize())
   141      ThrowTPE("Error reading TIFF structure (invalid size). File Corrupt");
   142
   143    bs.setByteOrder(getTiffByteOrder(bs, 0, "DNG makernote"));
   144    bs.skipBytes(2);
   145
   146    uint32 makerNoteOffset = bs.getU32();
   147    makerNoteSize -= 6; // update size of orinial maker note, we skipped 2+4 bytes
   148
   149    // Update the underlying buffer of t, such that the maker note data starts at its original offset
   150    bs.rebase(makerNoteOffset, makerNoteSize);
   151
   152    return parseMakerNote(ifds, t);
   153  }
