   155  /* This will attempt to parse makernotes and return it as an IFD */
   156  TiffRootIFDOwner TiffIFD::parseMakerNote(NORangesSet<Buffer>* ifds,
   157                                           TiffEntry* t) {
   158    assert(ifds);
   159
   160    // go up the IFD tree and try to find the MAKE entry on each level.
   161    // we can not go all the way to the top first because this partial tree
   162    // is not yet added to the TiffRootIFD.
   163    TiffIFD* p = this;
   164    TiffEntry* makeEntry;
   165    do {
   166      makeEntry = p->getEntryRecursive(MAKE);
   167      p = p->parent;
   168    } while (!makeEntry && p);
   169    string make = makeEntry != nullptr ? trimSpaces(makeEntry->getString()) : "";
   170
   171    ByteStream bs = t->getData();
   172
   173    // helper function for easy setup of ByteStream buffer for the different maker note types
   174    // 'rebase' means position 0 of new stream equals current position
   175    // 'newPosition' is the position where the IFD starts
   176    // 'byteOrderOffset' is the position wher the 2 magic bytes (II/MM) may be found
   177    // 'context' is a string providing error information in case the byte order parsing should fail
   178    auto setup = [&bs](bool rebase, uint32 newPosition,
   179                       uint32 byteOrderOffset = 0,
   180                       const char *context = nullptr) {
   181      if (rebase)
   182        bs = bs.getSubStream(bs.getPosition(), bs.getRemainSize());
   183      if (context)
   184        bs.setByteOrder(getTiffByteOrder(bs, byteOrderOffset, context));
   185      bs.skipBytes(newPosition);
   186    };
   187
   188    if (bs.hasPrefix("AOC\0", 4)) {
   189      setup(false, 6, 4, "Pentax makernote");
   190    } else if (bs.hasPrefix("PENTAX", 6)) {
   191      setup(true, 10, 8, "Pentax makernote");
   192    } else if (bs.hasPrefix("FUJIFILM\x0c\x00\x00\x00", 12)) {
   193      bs.setByteOrder(Endianness::little);
   194      setup(true, 12);
   195    } else if (bs.hasPrefix("Nikon\x00\x02", 7)) {
   196      // this is Nikon type 3 maker note format
   197      // TODO: implement Nikon type 1 maker note format
   198      // see http://www.ozhiker.com/electronics/pjmt/jpeg_info/nikon_mn.html
   199      bs.skipBytes(10);
   200      setup(true, 8, 0, "Nikon makernote");
   201    } else if (bs.hasPrefix("OLYMPUS", 7)) { // new Olympus
   202      setup(true, 12);
   203    } else if (bs.hasPrefix("OLYMP", 5)) {   // old Olympus
   204      setup(true, 8);
   205    } else if (bs.hasPrefix("EPSON", 5)) {
   206      setup(false, 8);
   207    } else if (bs.hasPatternAt("Exif", 4, 6)) {
   208      // TODO: for none of the rawsamples.ch files from Panasonic is this true, instead their MakerNote start with "Panasonic"
   209      // Panasonic has the word Exif at byte 6, a complete Tiff header starts at byte 12
   210      // This TIFF is 0 offset based
   211      setup(false, 20, 12, "Panosonic makernote");
   212    } else if (make == "SAMSUNG") {
   213      // Samsung has no identification in its MakerNote but starts with the IFD right away
   214      setup(true, 0);
   215    } else {
   216      // cerr << "default MakerNote from " << make << endl; // Canon, Nikon (type 2), Sony, Minolta, Ricoh, Leica, Hasselblad, etc.
   217
   218      // At least one MAKE has not been handled explicitly and starts its MakerNote with an endian prefix: Kodak
