    86  TiffEntry::TiffEntry(TiffIFD* parent_, TiffTag tag_, TiffDataType type_,
    87                       uint32 count_, ByteStream&& data_)
    88      : parent(parent_), data(std::move(data_)), tag(tag_), type(type_),
    89        count(count_) {
    90    // check for count << datashift overflow
    91    if (count > UINT32_MAX >> datashifts[type])
    92      ThrowTPE("integer overflow in size calculation.");
    93
    94    uint32 bytesize = count << datashifts[type];
    95
    96    if (data.getSize() != bytesize)
    97      ThrowTPE("data set larger than entry size given");
    98  }
