   178  float TiffEntry::getFloat(uint32 index) const {
   179    if (!isFloat()) {
   180      ThrowTPE("Wrong type 0x%x encountered. Expected Float or something "
   181               "convertible on 0x%x",
   182               type, tag);
   183    }
   184
   185    switch (type) {
   186    case TIFF_DOUBLE: return data.peek<double>(index);
   187    case TIFF_FLOAT:  return data.peek<float>(index);
   188    case TIFF_LONG:
   189    case TIFF_SHORT:
   190      return static_cast<float>(getU32(index));
   191    case TIFF_SLONG:
   192    case TIFF_SSHORT:
   193      return static_cast<float>(getI32(index));
   194    case TIFF_RATIONAL: {
   195      uint32 a = getU32(index*2);
   196      uint32 b = getU32(index*2+1);
   197      return b != 0 ? static_cast<float>(a) / b : 0.0F;
   198    }
   199    case TIFF_SRATIONAL: {
   200      auto a = static_cast<int>(getU32(index * 2));
   201      auto b = static_cast<int>(getU32(index * 2 + 1));
   202      return b ? static_cast<float>(a) / b : 0.0F;
   203    }
   204    default:
   205      // unreachable
   206      return 0.0F;
   207    }
   208  }
   209
   210  string TiffEntry::getString() const {
   211    if (type != TIFF_ASCII && type != TIFF_BYTE)
   212      ThrowTPE("Wrong type 0x%x encountered. Expected Ascii or Byte", type);
   213
   214    // *NOT* ByteStream::peekString() !
   215    const auto bufSize = data.getRemainSize();
   216    const auto* buf = data.peekData(bufSize);
   217    const auto* s = reinterpret_cast<const char*>(buf);
   218    return string(s, strnlen(s, bufSize));
   219  }
   220
   221  const DataBuffer &TiffEntry::getRootIfdData() const {
   222    TiffIFD* p = parent;
   223    TiffRootIFD* r = nullptr;
   224    while (p) {
   225      r = dynamic_cast<TiffRootIFD*>(p);
   226      if (r)
   227        break;
   228      p = p->parent;
   229    }
   230    if (!r)
   231      ThrowTPE("Internal error in TiffIFD data structure.");
   232
   233    assert(r != nullptr);
   234    return r->rootBuffer;
   235  }
